#!/usr/bin/env python3
"""omics/scrna_integrate — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "omics"
SKILL = "scrna_integrate"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'scrna_integrate', 'matrix_path': '', 'n_cells_post_qc': 0, 'cluster_sizes': {}, 'marker_genes_per_cluster': {}, 'umap_png': '', 'diagnostics': {'brain': 'omics', 'archetype': 'omics_scrna'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """多 batch 单细胞 integration via Harmony(harmonypy)。host_env=praxis-omics。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    h5ad_list = payload.get("h5ad_list") or []
    batch_col = payload.get("batch_col", "batch")
    out_h5ad = payload.get("out_h5ad") or _tempfile.NamedTemporaryFile(suffix="_integ.h5ad", delete=False).name
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "harmonypy", "n_batches": len(h5ad_list), "out_h5ad": out_h5ad}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "matrix_path": "", "n_cells_post_qc": 0,
                "cluster_sizes": {}, "marker_genes_per_cluster": {}, "umap_png": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not h5ad_list:
        return {"ok": False, "error": "需要 h5ad_list", "diagnostics": diagnostics}
    script = (
        "import json, sys, scanpy as sc, anndata as ad_mod\n"
        "import harmonypy as hm\n"
        f"files = {h5ad_list!r}; batch_col = {batch_col!r}; out = {out_h5ad!r}\n"
        "ads = [sc.read_h5ad(f) for f in files]\n"
        "for i, a in enumerate(ads): a.obs[batch_col] = f'batch_{i}'\n"
        "merged = ad_mod.concat(ads, label=batch_col, keys=[f'batch_{i}' for i in range(len(ads))], join='inner')\n"
        "sc.pp.normalize_total(merged); sc.pp.log1p(merged)\n"
        "sc.pp.highly_variable_genes(merged, n_top_genes=2000)\n"
        "sc.pp.scale(merged, max_value=10); sc.tl.pca(merged, n_comps=50)\n"
        "ho = hm.run_harmony(merged.obsm['X_pca'], merged.obs, [batch_col])\n"
        "merged.obsm['X_pca_harmony'] = ho.Z_corr.T\n"
        "sc.pp.neighbors(merged, use_rep='X_pca_harmony'); sc.tl.umap(merged); sc.tl.leiden(merged)\n"
        "merged.write_h5ad(out)\n"
        "cs = merged.obs['leiden'].value_counts().to_dict()\n"
        "json.dump({'matrix_path': out, 'n_cells_post_qc': int(merged.n_obs),\n"
        "           'cluster_sizes': {str(k):int(v) for k,v in cs.items()},\n"
        "           'marker_genes_per_cluster': {}}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "Harmony 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed, "umap_png": "",
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
